const query = $input.first().json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const expected = $env.FACEBOOK_VERIFY_TOKEN;
const verified = mode === 'subscribe' && typeof expected === 'string' && expected.length > 0 && token === expected;
return [{ json: { verified, challenge: challenge || '' } }];

// Facebook Page webhook, field "feed": one change per post/comment/reaction event.
const body = $input.first().json.body || {};
const events = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    if (change.field !== 'feed') continue;
    const v = change.value || {};
    if (v.item !== 'comment' || v.verb !== 'add') continue;   // only NEW comments
    const fullName = v.from ? (v.from.name || '') : '';
    events.push({
      json: {
        comment_id: v.comment_id,
        comment_text: v.message || '',
        post_id: v.post_id,
        from_id: v.from ? v.from.id : null,
        username: fullName.split(' ')[0] || null,   // first name for the greeting
        full_name: fullName || null,
        parent_id: v.parent_id || null,
        received_at: v.created_time
          ? new Date(v.created_time * 1000).toISOString()
          : new Date((entry.time || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
      },
    });
  }
}
return events;

function normalize(text) {
  return (text || '')
    .toString()
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
return { json: { ...$json, normalized_text: normalize($json.comment_text) } };

// EDIT HERE: add / reorder / remove rules. Priority = array order, first match wins.
// buttonTitle + buttonUrl : DM avec un bouton cliquable. Laisser buttonUrl vide ('') pour un simple texte.
// {{username}} = prenom de la personne (si Facebook le transmet).
// Limites Meta : texte du DM <= 640 caracteres, titre du bouton court (< 20 caracteres).
const rules = [
  {
    name: 'abc',
    keywords: ['abc', 'a-b-c', 'a b c'],
    dmMessages: [
      'Bonjour {{username}} 👋 Merci pour ton intérêt ! Voici ton guide gratuit « Les ABC de l\'IA » : prompts, images, vidéos et les meilleurs outils.',
    ],
    buttonTitle: '📘 Lire le guide',
    buttonUrl: 'https://broken-bison-10f.notion.site/Les-ABC-de-l-IA-Guide-pour-bien-d-marrer-4003c5701ae1818ebb64edbaacde90cf',
  },
];
const defaultDmMessages = [
  'Bonjour {{username}} 👋 Merci pour ton commentaire.',
];
return { json: { ...$json, rules, defaultDmMessages } };

function normalizeKeyword(k) {
  return k.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const text = $json.normalized_text || '';
let matched = null;
for (const rule of $json.rules) {
  const hit = rule.keywords.some((k) => text.includes(normalizeKeyword(k)));
  if (hit) { matched = rule; break; }
}
return {
  json: {
    ...$json,
    matched_rule: matched ? matched.name : null,
    matched_dm_messages: matched ? matched.dmMessages : $json.defaultDmMessages,
    button_title: matched && matched.buttonUrl ? (matched.buttonTitle || 'Ouvrir') : null,
    button_url: matched && matched.buttonUrl ? matched.buttonUrl : null,
  },
};

const list = ($json.matched_dm_messages && $json.matched_dm_messages.length) ? $json.matched_dm_messages : $json.defaultDmMessages;
const raw = list[Math.floor(Math.random() * list.length)];
const username = $json.username;
let text = raw.split('{{username}}').join(username || '').replace(/\s{2,}/g, ' ').trim();
// Safety net: never send a literal undefined/null or an unresolved {{...}} placeholder.
if (/undefined|null/i.test(text) || /\{\{.*?\}\}/.test(text)) {
  text = text.replace(/undefined|null/gi, '').replace(/\{\{.*?\}\}/g, '').replace(/\s{2,}/g, ' ').trim();
}
// Button Template: le texte est limite a 640 caracteres.
if ($json.button_url && text.length > 640) {
  text = text.slice(0, 637) + '...';
}
return { json: { ...$json, selected_dm: text } };

// La sortie HTTP ne contient que la reponse Meta : on recupere le contexte via l'item apparie.
const base = $('Select Random DM').item.json;
const body = $json.body || {};
return { json: { ...base, dm_status: 'sent', dm_message_id: body.message_id || null } };

// La sortie d'erreur HTTP ne contient que l'erreur : on recupere le contexte via l'item apparie.
const base = $('Select Random DM').item.json;
const err = $json.error || {};
// The exact shape of the error object can vary by n8n version - verify during testing.
const statusCode = Number(
  err.httpCode || err.statusCode || err.status ||
  (err.cause && (err.cause.httpCode || err.cause.statusCode)) || 0
);
const headers = err.headers || (err.cause && err.cause.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];
const attempt = $runIndex + 1;
const maxAttempts = 3;
const permanent = [400, 401, 403].includes(statusCode);
const transient = [429, 500, 502, 503, 504].includes(statusCode);
const canRetry = !permanent && transient && attempt < maxAttempts;
const waitSeconds = retryAfterHeader ? Number(retryAfterHeader) : Math.pow(2, attempt);
return {
  json: {
    ...base,
    dm_attempt: attempt,
    dm_status_code: statusCode || null,
    dm_error_message: (err.message || JSON.stringify(err)).toString().slice(0, 500),
    dm_can_retry: canRetry,
    dm_wait_seconds: waitSeconds,
  },
};

